    "requirement_statement": {
      "text": "Definitions: TypeSafe is the company whose API (application programming\ninterface) serves Jev, the judge model; the TypeSafe API key authenticates\ncalls to it. The platform credential store is the macOS Keychain, the\nWindows Credential Manager or, on Linux, the Secret Service (`secret-tool`).",
      "statements": [
        {
          "modal": "Must",
          "text": "judge-jev MUST use sc-agent's credential lookup: repository-root `.env`,\nthen the process environment, then the platform keyring."
        },
        {
          "modal": "Must",
          "text": "judge-jev MUST use the default TypeSafe keyring entry: service\n`TYPESAFE_API_KEY`, current OS account; it MUST pass no keyring selection\noptions."
        }
      ]
    },
    "rationale": "Tools that call Jev share one stored key, saved once.",
    "success_criteria": {
